fn min_inspectors(n: i8, d: i8) -> i8 {
    // Each inspector can cover a block of length 2*d + 1.
    let coverage = 2 * d + 1;
    // We need ceil(n / coverage). For positive integers this is:
    // (n + coverage - 1) / coverage
    (n + coverage - 1) / coverage
}

